<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import AppShell from '@/components/shell/AppShell.vue'
import BaseButton from '@/components/ui/BaseButton.vue'
import { renderMarkdown } from '@/utils/markdown'
import { usePracticeStore } from '@/stores/practiceStore'
import { errorCategoryLabel } from '@/utils/errorCategories'
import { ensureKnowledgeNames, kpLabel } from '@/utils/knowledgeNames'
const route=useRoute(),router=useRouter(),store=usePracticeStore()
const expanded=ref({})
const loadError=ref('')
const weakestPoint=computed(()=>store.result?.knowledge_breakdown?.reduce((weakest,row)=>!weakest||row.accuracy<weakest.accuracy?row:weakest,null))
const toggle=(id)=>{expanded.value[id]=!expanded.value[id]}
const duration=(seconds)=>seconds==null?'未记录':`${Math.floor(seconds/60)} 分 ${seconds%60} 秒`
const typeLabel=(item)=>item.error_classification?.question_type||''
async function loadResult(){
  loadError.value=''
  try { await store.loadResult(route.params.sessionId) }
  catch { loadError.value='结果暂时无法加载，请重试。' }
}
onMounted(()=>{ensureKnowledgeNames();loadResult()})
</script>
<template><AppShell><template #topbar-title>专项练习结果</template><main v-if="store.result" class="result"><p class="eyebrow">本组练习完成</p><h1 class="t-1">{{store.result.correct}} / {{store.result.total}} 题正确</h1><p>用时 {{duration(store.result.duration_seconds)}} · 本次结果仅代表本组练习。</p><section class="next-step card" aria-label="建议下一步"><span>建议下一步</span><h2>{{weakestPoint&&weakestPoint.accuracy<1?`先巩固「${kpLabel(weakestPoint.knowledge_point_code)}」`:'回顾本组练习'}}</h2><p>{{weakestPoint&&weakestPoint.accuracy<1?`该知识点正确率 ${Math.round(weakestPoint.accuracy*100)}%，从错题解析开始。`:'查看逐题回顾，确认解题方法。'}}</p><a href="#practice-review">查看逐题回顾</a></section><section class="card card-pad"><h2 class="t-2">知识点表现</h2><ul><li v-for="row in store.result.knowledge_breakdown" :key="row.knowledge_point_code"><span>{{kpLabel(row.knowledge_point_code)}}</span><span>{{row.correct}} / {{row.total}}（{{Math.round(row.accuracy*100)}}%）</span></li></ul></section><section v-if="store.result.error_breakdown?.length" class="card card-pad"><h2 class="t-2">错因分布</h2><ul><li v-for="row in store.result.error_breakdown" :key="row.category"><span>{{errorCategoryLabel(row.category)}}</span><span>{{row.count}} 题</span></li></ul></section><section id="practice-review" class="card card-pad"><h2 class="t-2">逐题回顾</h2><ul class="review"><li v-for="item in store.result.results" :key="item.question_id" :class="['review-item',item.correct?'ok':'bad']"><button class="review-head" :aria-expanded="expanded[item.question_id]?'true':'false'" @click="toggle(item.question_id)"><span class="badge">{{item.correct?'答对':'待改进'}}</span><span class="stem math" v-html="renderMarkdown(item.question_content||item.question_id)"/><span class="chevron" aria-hidden="true">{{expanded[item.question_id]?'收起':'展开'}}</span></button><div v-if="expanded[item.question_id]" class="review-body"><p><span class="label">你的答案</span>{{item.your_answer??'（未作答）'}}</p><p><span class="label">正确答案</span>{{item.correct_answer}}</p><p v-if="!item.correct&&item.error_category"><span class="label">错因</span>{{errorCategoryLabel(item.error_category)}}</p><div v-if="item.analysis"><span class="label">解析</span><div class="math" v-html="renderMarkdown(item.analysis)"/></div></div></li></ul></section><footer><BaseButton variant="secondary" size="lg" @click="router.push('/apply/practice')">按薄弱点再练</BaseButton><BaseButton variant="primary" size="lg" @click="router.push('/apply')">返回学以致用</BaseButton></footer></main><div v-else-if="loadError" class="loading" role="alert"><p>{{loadError}}</p><BaseButton variant="secondary" @click="loadResult">重试加载</BaseButton></div><p v-else class="loading" role="status">正在加载结果…</p></AppShell></template>
<style scoped>.result{max-width:880px;margin:0 auto;padding:38px 24px 80px}.eyebrow{display:inline-flex;align-items:center;height:26px;padding:0 12px;border-radius:var(--r-pill);border:1px solid var(--border);background:var(--surface);font-size:12px;color:var(--ink-2);font-weight:500;box-shadow:var(--shadow-1)}.result h1{margin:12px 0 6px}.result>p:not(.eyebrow){color:var(--ink-2);margin:0}section{margin-top:16px}section h2{margin:0 0 10px}ul{padding:0;list-style:none;margin:0}li{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px dashed var(--border)}li:last-child{border-bottom:0}li span:first-child{color:var(--ink-2)}.review .review-item{display:block;padding:0;border:1px solid var(--border);border-radius:var(--r-m);background:var(--surface);margin-top:10px;overflow:hidden}.review-head{display:flex;align-items:flex-start;gap:12px;width:100%;padding:14px 16px;border:0;background:transparent;text-align:left;font:inherit;cursor:pointer}.review-head:hover{background:var(--surface-2)}.badge{flex-shrink:0;padding:3px 10px;border-radius:7px;font-size:12px;font-weight:600}.ok .badge{background:var(--green-soft);color:var(--green)}.bad .badge{background:var(--rose-soft);color:var(--rose)}.stem{flex:1;color:var(--ink-1);line-height:1.6;max-height:66px;overflow:hidden}.chevron{flex-shrink:0;color:var(--ink-3);font-size:13px}.review-body{padding:0 16px 16px 58px;display:grid;gap:8px;color:var(--ink-1)}.review-body .label{display:inline-block;min-width:64px;color:var(--ink-3);font-size:13px}.review-body .math{line-height:1.7;margin-top:2px}footer{display:flex;gap:12px;margin-top:28px}.loading{padding:32px}@media(max-width:600px){.result{padding:28px 16px 64px}.review-body{padding-left:16px}}</style>
<style scoped>
.next-step{background:var(--brand-soft);border-color:transparent}.next-step>span{font-size:12px;font-weight:700;color:var(--brand-text)}.next-step h2{margin:8px 0!important;font-size:20px}.next-step p{margin:0 0 10px;color:var(--ink-2);line-height:1.6}.next-step a{color:var(--brand-text);font-weight:600}#practice-review{scroll-margin-top:24px}.result{max-width:1000px;padding-top:42px}.result>.eyebrow{background:var(--brand-soft-2);border-color:transparent;color:var(--brand-text);box-shadow:none}.result h1{font-size:clamp(30px,4vw,44px);letter-spacing:-.035em}.result>p:not(.eyebrow){margin-bottom:30px}.result>section{margin-top:20px;padding:26px 30px;border-radius:12px;box-shadow:var(--shadow-1)}.result section h2{margin-bottom:18px}.result section>ul:not(.review) li{align-items:center;min-height:42px;border-bottom:1px solid var(--border)}.result .review{display:grid;gap:12px}.result .review .review-item{margin:0;border-radius:10px}.result .review-head{align-items:center;min-height:70px;gap:16px;padding:18px 20px}.result .review-head:hover{background:var(--surface-2)}.result .badge{border-radius:6px;padding:5px 10px}.result .stem{max-height:70px;font-size:15px}.result .review-body{padding:4px 22px 22px 22px;gap:12px;line-height:1.7}.result .review-body>p{margin:0;padding:10px 14px;border-radius:8px;background:var(--surface-2)}.result .review-body .label{min-width:84px;font-weight:600}.result .review-body>div{padding-top:14px;border-top:1px solid var(--border)}.result footer{margin-top:30px}@media(max-width:600px){.result{padding:24px 14px 88px}.result>section{padding:20px 16px}.result .review-head{padding:14px;gap:10px}.result .review-body{padding:0 14px 16px}.result footer{flex-wrap:wrap}.result footer>*{flex:1}}
</style>
